package jp.personal.hanshinedge.validation;
import android.content.*;import android.os.SystemClock;import androidx.annotation.NonNull;import androidx.work.*;import androidx.work.testing.*;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.ext.junit.runners.AndroidJUnit4;import org.junit.*;import org.junit.runner.RunWith;import org.json.*;import java.util.concurrent.*;import jp.personal.hanshinedge.prospective.*;import jp.personal.hanshinedge.ui.MainActivity;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)public class RuntimeWorkerTest {
 @Test public void finishActivityThenWorkerAppendsAndReopenIsIdempotent()throws Exception{Context c=ProspectiveRuntimeTest.c();String prefix="test-worker";ProspectiveRuntimeTest.clear(prefix);long now=System.currentTimeMillis(),mono=SystemClock.elapsedRealtime();JSONObject raw=ProspectiveRuntimeTest.race(now+1200000);String id=ProspectiveRuntime.canonical(raw);try(ProspectiveRuntime r=new ProspectiveRuntime(c,prefix)){r.register(raw,ProspectiveRuntimeTest.receipt(now,mono),now,mono);}WorkerFactory factory=new WorkerFactory(){@Override public ListenableWorker createWorker(@NonNull Context ctx,@NonNull String name,@NonNull WorkerParameters params){if(!name.equals(RuntimeWorker.class.getName()))return null;return new RuntimeWorker(ctx,params,(app,r,raceId,stage)->{long at=System.currentTimeMillis(),m=SystemClock.elapsedRealtime();r.capture(raceId,stage,raw,ProspectiveRuntimeTest.receipt(at,m),at,m);r.shadow(raceId);});}};WorkManagerTestInitHelper.initializeTestWorkManager(c,new Configuration.Builder().setExecutor(new SynchronousExecutor()).setWorkerFactory(factory).build());android.app.Instrumentation instr=InstrumentationRegistry.getInstrumentation();MainActivity activity=(MainActivity)instr.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));instr.runOnMainSync(activity::finish);instr.waitForIdleSync();assertTrue(activity.isFinishing());WorkManager wm=WorkManager.getInstance(c);try(ProspectiveRuntime r=new ProspectiveRuntime(c,prefix)){BackgroundScheduler.schedule(c,prefix,r.registration(id));}java.util.List<WorkInfo> works=wm.getWorkInfosForUniqueWork(prefix+":"+id+":T-20").get(20,TimeUnit.SECONDS);assertEquals(1,works.size());java.util.UUID workId=works.get(0).getId();WorkManagerTestInitHelper.getTestDriver(c).setAllConstraintsMet(workId);assertEquals(WorkInfo.State.SUCCEEDED,wm.getWorkInfoById(workId).get(20,TimeUnit.SECONDS).getState());try(ProspectiveRuntime r=new ProspectiveRuntime(c,prefix)){assertEquals(1,r.runtime.timechainStatus().getInt("count"));assertEquals(0,r.runtime.formalBuyStatus().getInt("count"));assertEquals(0,r.runtime.settlementStatus().getInt("count"));}OneTimeWorkRequest retry=new OneTimeWorkRequest.Builder(RuntimeWorker.class).setInputData(new Data.Builder().putString("prefix",prefix).putString("race_id",id).putString("stage","T-20").build()).build();wm.enqueue(retry).getResult().get(20,TimeUnit.SECONDS);try(ProspectiveRuntime r=new ProspectiveRuntime(c,prefix)){assertEquals(1,r.runtime.timechainStatus().getInt("count"));assertTrue(r.runtime.timechainStatus().getBoolean("verified"));c.getSharedPreferences("test-worker-anchor",0).edit().putString("head",r.runtime.timechainStatus().getString("head")).commit();}}
}
